void IssueFilterModel::setSearch(const QString &text) {
    beginFilterChange();
    m_words = text.toLower().split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    endFilterChange();
}

void IssueFilterModel::setSortKey(int key) { m_sort = key; invalidate(); }
void IssueFilterModel::setCollation(const QLocale &l) { m_collator = QCollator(l); m_keys.clear(); if (m_sort == 3) invalidate(); }

bool IssueFilterModel::filterAcceptsRow(int row, const QModelIndex &) const {
    const Issue &i = m_src->at(row);
    switch (m_view) {
    case 0: if (i.closed) return false; break;
    case 1: if (i.closed || i.assignee != QLatin1String("Ada Okafor")) return false; break;
    case 2: if (!i.starred) return false; break;
    case 3: if (!i.closed) return false; break;
    case 4: if (i.closed || !i.tags.contains(m_tag)) return false; break;
    }
    for (const QString &w : m_words)
        if (!i.hay.contains(w)) return false;
    return true;
}

